// === Tab: mySketch ===
//Chaosphere_6.0

let N = 10000 ; let dROT = 0.01 ; let Qmax = 2 ; 
let Zmin = -sqrt(pow(280,2)-pow(250,2)) ; let PA = 2*PI/3 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ; let Z[] = new Array(N) ;
let I ; let A ; let R ; let KA ; let Rot ; let Q ;
let KX ; let KY ; let KZ ; let T ; let dT ; let dA ;

function setup(){
  createCanvas(600, 600) ; noSmooth() ; background(0) ; fill(0,0,0,20) ;
  KX = random(+20,+200) ; 
  for ( I = 0 ; I < N ; I++ ){
    X[I] = KX+random(-10,+10) ; R = sqrt(pow(280,2)-pow(X[I],2)) ;
    A = random(-PI,+PI) ; Y[I] = R*cos(A) ; Z[I] = R*sin(A) ; 
  }//I
}//setup()

function draw(){
  background(0) ; noStroke() ; 
  for ( I = 0 ; I < 100 ; I++ ){ fill(0,0,250-(125*I/100)) ; arc(300,300,500*(100-I)/100,500,PI/2,3*PI/2) ; }
  for ( I = 0 ; I < 100 ; I++ ){ fill(0,0,125*I/100) ; arc(300,300,500*(100-I)/100,500,-PI/2,+PI/2) ; }
  stroke(255) ;
  for ( Q = 0 ; Q < Qmax ; Q++ ){
  for ( I = 0 ; I < N ; I++ ){
    A = atan(Y[I]/X[I]) ; R = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
    if ( X[I] < 0 ){ A = A+PI ; }
    if ( X[I] >= 0 && Y[I] < 0 ){ A = A+(2*PI) ; }
    T = 2*acos(-A/PI+1) ; T = T+dT ; while ( T > 2*PI ){ T = T-(2*PI) ; }
    KA = (1-cos(T/2))*PI ;
    X[I] = R*cos(KA) ; Y[I] = R*sin(KA) ; 
    A = atan(Y[I]/Z[I]) ; R = sqrt(pow(Y[I],2)+pow(Z[I],2)) ;
    if ( Z[I] < 0 ){ A = A+PI ; }
    if ( Z[I] >= 0 && Y[I] < 0 ){ A = A+(2*PI) ; }
    KA = A+dA ; while( KA > 2*PI ){ KA = KA-(2*PI) ; }
    Z[I] = R*cos(KA) ; Y[I] = R*sin(KA) ; 
    KX = (X[I]*cos(Rot)) - (Z[I]*sin(Rot)) ;
    KZ = (X[I]*sin(Rot)) + (Z[I]*cos(Rot)) ;
    KY = Y[I] ;
    if ( KZ > Zmin ){ stroke(-KX/2.5+125) ; point(KX+300,KY+300) ; }
  }//I
  }//let dA = float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-300)/1000 + PI ;
  dT = float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-300)/100 + PI ;
  Rot = Rot+dROT ;
}//draw()

function mousePressed(){ setup() ; }

